import networkx as nx
import itertools

g = nx.Graph()
g.add_nodes_from(range(8))
g.add_edges_from([(2,7), (0,5)])

for r in range(1, 5):
    for subset in itertools.combinations(range(8), r):
        if len(subset) > 4:
            continue
        sub_g = g.subgraph(subset)
        if nx.is_clique(sub_g):
            clique_size = len(subset)
            if clique_size > 4:
                print("UNSATISFIABLE")
                break

for node in g.nodes:
    if g.degree(node) < 1:
        print("UNSATISFIABLE")
        break

